use crate::actions::Target;
use crate::cards::{CardBehavior, CardData, TargetRequirement, CardRegistry};
use crate::ids::{ObjectId, PlayerId};
use crate::state::{GameState, LogLevel};
use crate::types::*;

/// Counterspell — {U}{U} instant. Counter target spell.
pub struct Counterspell;

impl CardBehavior for Counterspell {
    fn card_data(&self) -> CardData {
        CardData {
            name: "Counterspell".into(),
            cost: Some(ManaCost::new(vec![
                ManaSymbol::Colored(Color::Blue),
                ManaSymbol::Colored(Color::Blue),
            ])),
            card_types: vec![CardType::Instant],
            supertypes: vec![],
            subtypes: vec![],
            power: None,
            toughness: None,
            oracle_text: "Counter target spell.".into(),
            keywords: vec![],
            flashback_cost: None, continuous_effects: vec![], additional_cost: None, triggered_abilities: vec![],
        }
    }

    fn target_requirement(&self) -> TargetRequirement {
        TargetRequirement::Spell
    }

    fn is_valid_target(&self, state: &GameState, _caster: PlayerId, target: &Target, _registry: &CardRegistry) -> bool {
        match target {
            Target::Object(id) => {
                state.get_object(*id)
                    .map(|o| o.zone == Zone::Stack)
                    .unwrap_or(false)
            }
            Target::Player(_) => false,
        }
    }

    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, targets: &[Target], _registry: &CardRegistry) {
        if let Some(Target::Object(target_id)) = targets.first() {
            if let Some(obj) = state.get_object(*target_id) {
                if obj.zone == Zone::Stack {
                    let name = obj.name.clone();
                    state.stack.retain(|e| e.as_spell() != Some(*target_id));
                    state.move_spell_after_resolve(*target_id);
                    state.log(LogLevel::Event, format!("{} was countered", name));
                }
            }
        }
        state.move_spell_after_resolve(object_id);
    }
}

pub enum Keyword {
    Flying,
    FirstStrike,
    DoubleStrike,
    Trample,
    Deathtouch,
    Lifelink,
    Vigilance,
    Flash,
    Reach,
    Haste,
    Defender,
    Hexproof,
    Intimidate,
    Menace,
    Indestructible,
}

/// Describes which creatures a continuous effect applies to.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum CreatureFilter {
    /// All creatures you control.
    You,
    /// All creatures opponents control.
    Opponents,
    /// Token creatures you control.
    YourTokens,
    /// Creatures matching a subtype (e.g., "Human", "Zombie").
    HasSubtype(String),
    /// Creatures with a specific keyword.
    HasKeyword(Keyword),
    /// Intersection: all conditions must match.
    And(Vec<CreatureFilter>),
    /// Union: any condition matches.
    Or(Vec<CreatureFilter>),
    /// Negation.
    Not(Box<CreatureFilter>),
    /// Creatures controlled by the player this curse/aura is attached to.
    AttachedPlayer,
}

/// Where a continuous effect applies.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum EffectScope {
    /// Affects only the permanent this effect is on (static keyword on a creature).
    OnSelf,
    /// Affects the creature this aura/equipment is attached to.
    Attached,
    /// Affects all creatures matching a filter, INCLUDING the source permanent.
    /// Used for "Creatures you control get +1/+1" (Glorious Anthem).

